import csv, json, os
from collections import deque
from pathlib import Path

NODE_DIR = Path(os.environ["NODE_FLOW_DIR"])
PIPE_DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
OUT_DIR = Path(os.environ["OUTPUT_DIR"])
date = "20190114"
pipe_csv = PIPE_DIR / f"{date}_pipeline.csv"

with pipe_csv.open(encoding="utf-8-sig", newline="") as f:
    r = csv.DictReader(f)
    rows = list(r)
    fields = r.fieldnames

print("FIELDS:", fields)
print("ROWS:", len(rows))
print("SAMPLE:", rows[0] if rows else None)

# build undirected adjacency on station names, remembering pipeline of the edge
adj = {}
for row in rows:
    s = row.get("source") or row.get("起点") or ""
    t = row.get("target") or row.get("终点") or ""
    p = row.get("pipeline") or row.get("管道名称") or ""
    if not s or not t:
        continue
    adj.setdefault(s, set()).add((t, p))
    adj.setdefault(t, set()).add((s, p))

target = "石家庄站"
sources = ["靖边站", "榆林站", "霍尔果斯首站"]

def bfs(src):
    q = deque([src])
    prev = {src: None}
    while q:
        cur = q.popleft()
        if cur == target:
            break
        for nxt, p in sorted(adj.get(cur, ())):
            if nxt not in prev:
                prev[nxt] = (cur, p)
                q.append(nxt)
    if target not in prev:
        return None
    nodes, pipes = [], []
    cur = target
    while prev[cur] is not None:
        pc, p = prev[cur]
        nodes.append(cur)
        pipes.append(p)
        cur = pc
    nodes.append(cur)
    nodes.reverse()
    pipes.reverse()
    return {"nodes": nodes, "pipelines": pipes}

result = {}
for s in sources:
    if s not in adj:
        result[s] = {"error": "source not present in pipeline adjacency"}
        continue
    r_ = bfs(s)
    if r_ is None:
        result[s] = {"error": "no path"}
    else:
        result[s] = {
            "hop_count": len(r_["nodes"]) - 1,
            "nodes": r_["nodes"],
            "pipelines": r_["pipelines"],
            "intermediate_stations": r_["nodes"][1:-1],
        }

payload = {
    "date": date,
    "target_station": target,
    "paths": result,
    "adjacency_size": len(adj),
    "direct_inbound_edges": sorted(
        [(s, t, p) for s, nbrs in adj.items() for (t, p) in nbrs if t == target and s != target]
    ),
}
OUT_DIR.mkdir(parents=True, exist_ok=True)
(OUT_DIR / "shortest_paths_20190114.json").write_text(
    json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8"
)
print(json.dumps(payload, ensure_ascii=False, indent=2))

import json
import os
from collections import deque
from pathlib import Path

PIPE_DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
OUT_DIR = Path(os.environ["OUTPUT_DIR"])
date = "20190114"
target = "石家庄站"
sources = ["靖边站", "榆林站", "霍尔果斯首站"]

import csv

with (PIPE_DIR / f"{date}_pipeline.csv").open(encoding="utf-8-sig", newline="") as f:
    rows = list(csv.DictReader(f))

# directed adjacency: edge is 起点站名 -> 终点站名 on 管道划分
adj = {}
flows = {}
for r in rows:
    s = r["起点站名"].strip()
    t = r["终点站名"].strip()
    p = r["管道划分"].strip()
    if not s or not t:
        continue
    adj.setdefault(s, set()).add((t, p))
    flows[(s, t, p)] = r["管道流量"].strip()


def bfs(src):
    if src not in adj:
        return {"error": "source has no outgoing segment in pipeline table"}
    q = deque([src])
    prev = {src: None}
    while q:
        cur = q.popleft()
        for nxt, p in sorted(adj.get(cur, ())):
            if nxt not in prev:
                prev[nxt] = (cur, p)
                q.append(nxt)
    if target not in prev:
        return {"error": "no directed path to target"}
    nodes, pipes = [target], []
    cur = target
    while prev[cur] is not None:
        pc, p = prev[cur]
        pipes.append(p)
        nodes.append(pc)
        cur = pc
    nodes.reverse()
    pipes.reverse()
    legs = [
        {
            "from": nodes[i],
            "to": nodes[i + 1],
            "pipeline": pipes[i],
            "flow": flows.get((nodes[i], nodes[i + 1], pipes[i])),
        }
        for i in range(len(pipes))
    ]
    return {
        "hop_count": len(nodes) - 1,
        "path_nodes": nodes,
        "intermediate_stations": nodes[1:-1],
        "legs": legs,
    }


payload = {
    "date": date,
    "source_files": [f"{date}_node.csv", f"{date}_pipeline.csv"],
    "target_station": target,
    "graph_direction": "directed 起点站名 -> 终点站名",
    "paths": {s: bfs(s) for s in sources},
    "direct_inbound_segments": [
        {
            "from": r["起点站名"].strip(),
            "to": r["终点站名"].strip(),
            "pipeline": r["管道划分"].strip(),
            "flow": r["管道流量"].strip(),
        }
        for r in rows
        if r["终点站名"].strip() == target
    ],
}
OUT_DIR.mkdir(parents=True, exist_ok=True)
(OUT_DIR / "shortest_paths_20190114.json").write_text(
    json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8"
)
print(json.dumps(payload, ensure_ascii=False, indent=2))

