import os, csv
from pathlib import Path
from collections import defaultdict

DIR = Path(os.environ["CONSUMER_FLOW_DIR"])
csv_path = DIR / "20190114_consumer.csv"

rows = []
with open(csv_path, encoding="utf-8") as f:
    for r in csv.DictReader(f):
        rows.append(r)

def val(r):
    try:
        return float(r["消耗量"])
    except Exception:
        return None

points = defaultdict(set)
total = defaultdict(float)
for r in rows:
    u = r["用户"]
    points[u].add(r["供气点"])
    v = val(r)
    if v is not None:
        total[u] += v

print("columns:", list(rows[0].keys()))
print("global top5 by total consumption:")
for u, s in sorted(total.items(), key=lambda kv: -kv[1])[:5]:
    print("  ", u, round(s, 3), "| points:", sorted(points[u]))

print("hebei top3:")
hb = defaultdict(float)
hbp = defaultdict(set)
hbn = defaultdict(int)
for r in rows:
    if r["所属地"] == "河北":
        v = val(r) or 0.0
        hb[r["用户"]] += v
        hbp[r["用户"]].add(r["供气点"])
        hbn[r["用户"]] += 1
for u, s in sorted(hb.items(), key=lambda kv: -kv[1])[:3]:
    print("  ", u, round(s, 3), "| points:", sorted(hbp[u]), "| rows:", hbn[u])

print("all users with >1 distinct 供气点:")
for u in sorted(points, key=lambda x: -total[x]):
    if len(points[u]) > 1:
        print("  ", u, "| points:", len(points[u]), sorted(points[u]), "| total:", round(total[u], 3))

