import os, csv
from pathlib import Path

node_dir = Path(os.environ["NODE_FLOW_DIR"])
cons_dir = Path(os.environ["CONSUMER_FLOW_DIR"])

def f(x):
    x = (x or "").strip()
    return float(x) if x else 0.0

node_demand = {}
with open(node_dir / "20190114_node.csv", encoding="utf-8-sig", newline="") as fh:
    for r in csv.DictReader(fh):
        if (r.get("类型") or "").strip() == "需求":
            name = (r.get("站名") or "").strip()
            node_demand[name] = node_demand.get(name, 0.0) + f(r.get("计算流量"))

cons_by_point = {}
with open(cons_dir / "20190114_consumer.csv", encoding="utf-8-sig", newline="") as fh:
    for r in csv.DictReader(fh):
        p = (r.get("供气点") or "").strip()
        cons_by_point.setdefault(p, []).append(f(r.get("消耗量")))

# try exact and normalized match (strip 分输站/压气站/末站/站 suffix)
def norm(s):
    for suf in ("分输站", "压气站", "末站", "站"):
        if s.endswith(suf):
            return s[: -len(suf)]
    return s

node_norm = {norm(k): v for k, v in node_demand.items()}
unmatched = {}
for p, vals in cons_by_point.items():
    key = norm(p)
    if p not in node_demand and key not in node_norm:
        unmatched[p] = round(sum(vals), 3)

print("node demand station count:", len(node_demand))
print("consumer 供气点 count:", len(cons_by_point))
print("unmatched consumer points:", len(unmatched))
for k, v in sorted(unmatched.items(), key=lambda kv: -kv[1]):
    print("  ", k, v)
print("unmatched sum:", round(sum(unmatched.values()), 3))

import os, csv
from pathlib import Path

node_dir = Path(os.environ["NODE_FLOW_DIR"])
cons_dir = Path(os.environ["CONSUMER_FLOW_DIR"])

def f(x):
    x = (x or "").strip()
    return float(x) if x else 0.0

def norm(s):
    for suf in ("分输站", "压气站", "末站", "站"):
        if s.endswith(suf):
            return s[: -len(suf)]
    return s

node_types = {}
with open(node_dir / "20190114_node.csv", encoding="utf-8-sig", newline="") as fh:
    for r in csv.DictReader(fh):
        node_types.setdefault(norm((r.get("站名") or "").strip()), set()).add((r.get("类型") or "").strip())

cons_by_point = {}
with open(cons_dir / "20190114_consumer.csv", encoding="utf-8-sig", newline="") as fh:
    for r in csv.DictReader(fh):
        p = (r.get("供气点") or "").strip()
        cons_by_point.setdefault(p, 0.0)
        cons_by_point[p] += f(r.get("消耗量"))

cats = {"matched_demand": 0.0, "matched_non_demand": 0.0, "absent_in_node": 0.0}
detail = []
for p, v in sorted(cons_by_point.items(), key=lambda kv: -kv[1]):
    key = norm(p)
    types = node_types.get(key)
    if types is None:
        cats["absent_in_node"] += v
        detail.append((p, round(v, 3), "absent"))
    elif "需求" in types:
        cats["matched_demand"] += v
    else:
        cats["matched_non_demand"] += v
        detail.append((p, round(v, 3), "/".join(sorted(types))))

for k, v in cats.items():
    print(k, round(v, 3))
print("--- non-demand or absent points ---")
for d in detail:
    print("  ", d)

import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
NDIR = Path(os.environ["NODE_FLOW_DIR"])
lines = ["西气东输二线", "西气东输三线"]
out = {}
for date in ["20191204", "20191205", "20191206"]:
    p = DIR / f"{date}_pipeline.csv"
    n = NDIR / f"{date}_node.csv"
    seg = {l: {"sum_abs": 0.0, "n": 0, "negative": 0} for l in lines}
    found_cols = None
    with open(p, encoding="utf-8-sig", newline="") as f:
        r = csv.DictReader(f)
        found_cols = r.fieldnames
        for row in r:
            ln = (row.get("管道划分") or "").strip()
            if ln in seg:
                try:
                    v = float(row.get("管道流量") or 0)
                except ValueError:
                    continue
                seg[ln]["sum_abs"] += abs(v)
                seg[ln]["n"] += 1
                if v < 0:
                    seg[ln]["negative"] += 1
    # check node file line membership too
    nlines = set()
    with open(n, encoding="utf-8-sig", newline="") as f:
        for row in csv.DictReader(f):
            nlines.add((row.get("管道划分") or "").strip())
    out[date] = {"cols": found_cols, "segments": seg, "node_line_values": sorted(nlines)}

window = {}
for l in lines:
    window[l] = round(sum(out[d]["segments"][l]["sum_abs"] for d in out), 3)
print(json.dumps({"per_day": out, "window_totals": window,
                  "diff_saner_minus_san": round(window["西气东输三线"] - window["西气东输二线"], 3)},
                 ensure_ascii=False, indent=1))

