import os, csv, json
from collections import deque
from pathlib import Path

NDIR = Path(os.environ["NODE_FLOW_DIR"])
PDIR = Path(os.environ["PIPELINE_FLOW_DIR"])
date = "20190114"

nodes = list(csv.DictReader(open(NDIR / f"{date}_node.csv", encoding="utf-8-sig")))
pipes = list(csv.DictReader(open(PDIR / f"{date}_pipeline.csv", encoding="utf-8-sig")))

sources = sorted({r["站名"] for r in nodes if r["类型"].strip() == "气源"})
target = "南通站"

adj = {}
for r in pipes:
    a, b = r["起点站名"].strip(), r["终点站名"].strip()
    adj.setdefault(a, []).append((b, r["管道划分"].strip(), r["管道流量"].strip()))

def bfs(src, directed=True):
    q = deque([(src, [])])
    seen = {src}
    while q:
        cur, path = q.popleft()
        if cur == target:
            return path
        for nb, pl, fl in adj.get(cur, []):
            if nb not in seen:
                seen.add(nb)
                q.append((nb, path + [{"from": cur, "to": nb, "pipeline": pl, "flow": fl}]))
    return None

out = {"sources": sources, "directed": {}, "undirected_hops": {}}
for s in sources:
    p = bfs(s, True)
    if p is not None:
        out["directed"][s] = {"hops": len(p), "path": p}

# undirected variants
uadj = {}
for r in pipes:
    a, b = r["起点站名"].strip(), r["终点站名"].strip()
    uadj.setdefault(a, []).append((b, r["管道划分"].strip(), r["管道流量"].strip()))
    uadj.setdefault(b, []).append((a, r["管道划分"].strip(), r["管道流量"].strip()))

def bfs_u(src):
    q = deque([(src, [])])
    seen = {src}
    while q:
        cur, path = q.popleft()
        if cur == target:
            return path
        for nb, pl, fl in uadj.get(cur, []):
            if nb not in seen:
                seen.add(nb)
                q.append((nb, path + [{"from": cur, "to": nb, "pipeline": pl, "flow": fl}]))
    return None

for s in sources:
    p = bfs_u(s)
    if p is not None:
        out["undirected_hops"][s] = {"hops": len(p), "path": p}

print(json.dumps(out, ensure_ascii=False, indent=1))

