arguments.content:
import os, csv, json
from collections import deque
from pathlib import Path

PDIR = Path(os.environ["PIPELINE_FLOW_DIR"])
date = "20191206"
edges = []
with open(PDIR / f"{date}_pipeline.csv", encoding="utf-8-sig") as f:
    for r in csv.DictReader(f):
        edges.append((r["起点站名"].strip(), r["终点站名"].strip(), r["管道划分"].strip(), r["类型"].strip()))

target = "石家庄站"

def bfs(rows):
    rev = {}
    for s, t, p, k in rows:
        rev.setdefault(t, []).append((s, p))
    prev = {target: None}
    dist = {target: 0}
    q = deque([target])
    while q:
        n = q.popleft()
        for s, p in rev.get(n, []):
            if s not in dist:
                dist[s] = dist[n] + 1
                prev[s] = (n, p)
                q.append(s)
    return dist, prev

full_dist, full_prev = bfs(edges)
jn = [e for e in edges if e[2] == "冀宁线"]
jn_dist, jn_prev = bfs(jn)

def path(prev, src):
    out = []
    cur = src
    while prev.get(cur) is not None:
        nxt, p = prev[cur]
        out.append({"from": cur, "to": nxt, "pipeline": p})
        cur = nxt
    return out

sources_full = sorted([(d, s) for s, d in full_dist.items() if s.endswith("首站") or ("气源" in s)], key=lambda x: x[0])
res = {
    "full_reachable": sorted([(s, d) for s, d in full_dist.items() if s != target], key=lambda x: x[1]),
    "jn_reachable": sorted([(s, d) for s, d in jn_dist.items() if s != target], key=lambda x: x[1]),
    "full_paths": {},
    "jn_paths": {},
}
for s, d in res["full_reachable"]:
    res["full_paths"][s] = {"hops": d, "path": path(full_prev, s)}
for s, d in res["jn_reachable"]:
    res["jn_paths"][s] = {"hops": d, "path": path(jn_prev, s)}
print(json.dumps(res, ensure_ascii=False, indent=1))

