import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190125", "20190126"]
targets = ["西气东输一线", "陕京二线"]

rows = {}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    with open(p, encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            line = r["管道划分"].strip()
            if line in targets:
                rows.setdefault((d, line), []).append(
                    (r["起点站名"].strip(), r["终点站名"].strip(), float(r["管道流量"]))
                )

out = {}
for line in targets:
    per_day = {}
    for d in dates:
        vals = [v for _, _, v in rows.get((d, line), [])]
        per_day[d] = {
            "segments": len(vals),
            "daily_mean": round(sum(vals) / len(vals), 3) if vals else None,
            "min": min(vals) if vals else None,
            "max": max(vals) if vals else None,
            "range": round(max(vals) - min(vals), 3) if vals else None,
        }
    means = [per_day[d]["daily_mean"] for d in dates if per_day[d]["daily_mean"] is not None]
    allv = [v for d in dates for _, _, v in rows.get((d, line), [])]
    out[line] = {
        "per_day": per_day,
        "mean_of_daily_means": round(sum(means) / len(means), 3) if means else None,
        "range_of_daily_means": round(max(means) - min(means), 3) if means else None,
        "pooled_min": min(allv) if allv else None,
        "pooled_max": max(allv) if allv else None,
        "pooled_range": round(max(allv) - min(allv), 3) if allv else None,
        "segments": [
            {"date": d, "from": a, "to": b, "flow": v}
            for d in dates for a, b, v in rows.get((d, line), [])
        ],
    }

# excluding the small 阳曲压气站 branch for sensitivity
sens = {}
for line in targets:
    vals_by_day = {}
    for d in dates:
        vals = [v for a, b, v in rows.get((d, line), []) if b != "阳曲压气站"]
        vals_by_day[d] = round(sum(vals) / len(vals), 3)
    sens[line] = vals_by_day

print(json.dumps({"by_line": out, "sens_excl_yangqu": sens}, ensure_ascii=False, indent=2, default=str))

