import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
OUT = Path(os.environ["OUTPUT_DIR"])
dates = ["20190223", "20190307"]
targets = ["西气东输二线", "冀宁线"]

res = {}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    rows = list(csv.DictReader(p.open(encoding="utf-8-sig")))
    per = {}
    for r in rows:
        line = r["管道划分"].strip()
        if line in targets:
            q = abs(float(r["管道流量"]))
            e = per.setdefault(line, {"segments": 0, "abs_flow_sum": 0.0})
            e["segments"] += 1
            e["abs_flow_sum"] += q
    res[d] = {k: {"segments": v["segments"], "abs_flow_sum": round(v["abs_flow_sum"], 3)} for k, v in per.items()}

diffs = {}
for d in dates:
    a = res[d].get("西气东输二线", {}).get("abs_flow_sum")
    b = res[d].get("冀宁线", {}).get("abs_flow_sum")
    if a is not None and b is not None:
        diffs[d] = {"xier_minus_jining": round(a - b, 3), "ratio": round(a / b, 3)}

out = {"per_date": res, "diff": diffs}
(OUT / "flow_compare_result.json").write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")
print(json.dumps(out, ensure_ascii=False, indent=2))

