import os, csv, json
from pathlib import Path
from statistics import mean

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190102", "20190103", "20190105", "20190108", "20190111"]
targets = ["西气东输三线", "中俄东线"]

out = {}
missing = []
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    rows = []
    with open(p, encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            rows.append(r)
    per = {}
    for t in targets:
        vals = []
        for r in rows:
            if (r.get("管道划分") or "").strip() == t:
                try:
                    vals.append(float(r["管道流量"]))
                except (KeyError, ValueError):
                    pass
        per[t] = {"count": len(vals), "mean": mean(vals) if vals else None,
                  "min": min(vals) if vals else None, "max": max(vals) if vals else None}
    out[d] = {"file": p.name, "rows": len(rows),
              "all_lines": sorted({(r.get("管道划分") or "").strip() for r in rows}),
              "per_line": per}

summary = {}
for t in targets:
    daily = [out[d]["per_line"][t] for d in dates]
    means = [x["mean"] for x in daily if x["mean"] is not None]
    allvals = []
    for d in dates:
        p = DIR / f"{d}_pipeline.csv"
        with open(p, encoding="utf-8-sig") as f:
            for r in csv.DictReader(f):
                if (r.get("管道划分") or "").strip() == t:
                    allvals.append(float(r["管道流量"]))
    summary[t] = {
        "days_with_data": len(means),
        "daily_means": means,
        "mean_of_daily_means": mean(means) if means else None,
        "range_of_daily_means": (max(means) - min(means)) if means else None,
        "segment_count_total": len(allvals),
        "overall_min": min(allvals) if allvals else None,
        "overall_max": max(allvals) if allvals else None,
    }

print(json.dumps({"per_day": out, "summary": summary}, ensure_ascii=False, indent=2, default=str))

import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
OUT = Path(os.environ["OUTPUT_DIR"])
dates = ["20191203", "20191204", "20191205", "20191206", "20191207"]
targets = ["川气东送", "西气东输二线"]

summary = {t: [] for t in targets}
detail = {}

for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    rows = list(csv.DictReader(p.open(encoding="utf-8-sig")))
    detail[d] = {}
    for t in targets:
        sel = [r for r in rows if t in r["管道划分"]]
        vals = [float(r["管道流量"]) for r in sel]
        if vals:
            mean = sum(vals) / len(vals)
            summary[t].append(round(mean, 3))
            detail[d][t] = {"n_segments": len(vals), "mean_flow": round(mean, 3),
                            "min": round(min(vals), 3), "max": round(max(vals), 3)}
        else:
            summary[t].append(None)
            detail[d][t] = {"n_segments": 0}

res = {}
for t in targets:
    s = [v for v in summary[t] if v is not None]
    res[t] = {
        "daily_means": summary[t],
        "mean_of_daily_means": round(sum(s) / len(s), 3) if s else None,
        "range": round(max(s) - min(s), 3) if s else None,
        "days_present": len(s),
    }

payload = {"dates": dates, "per_day": detail, "aggregate": res}
(OUT / "pipeline_5day_compare.json").write_text(
    json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
print(json.dumps(payload, ensure_ascii=False, indent=2))

import os, csv, json, statistics
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
OUT = Path(os.environ["OUTPUT_DIR"])
dates = ["20190114", "20190115", "20190116", "20190119", "20190120", "20190121"]

rows = {}   # (start,end) -> {date: value}
types = {}
plan = {}
missing = []
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    with open(p, encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            types[r["类型"]] = types.get(r["类型"], 0) + 1
            plan[r["管道划分"]] = plan.get(r["管道划分"], 0) + 1
            if r["管道划分"].strip() != "西气东输一线":
                continue
            if r["类型"].strip() != "管段":
                continue
            k = (r["起点站名"].strip(), r["终点站名"].strip())
            try:
                v = float(r["管道流量"])
            except (TypeError, ValueError):
                missing.append((d, k, r["管道流量"]))
                v = None
            rows.setdefault(k, {})[d] = v

res = []
for k, dv in rows.items():
    vals = [dv.get(d) for d in dates]
    if any(v is None for v in vals):
        res.append({"segment": list(k), "values": vals, "n": sum(v is not None for v in vals), "incomplete": True})
        continue
    res.append({
        "segment": list(k),
        "values": vals,
        "n": len(vals),
        "mean": statistics.fmean(vals),
        "std_pop": statistics.pstdev(vals),
        "std_sample": statistics.stdev(vals) if len(vals) > 1 else 0.0,
        "min": min(vals), "max": max(vals), "range": max(vals) - min(vals),
        "incomplete": False,
    })

res.sort(key=lambda x: x.get("std_pop", -1), reverse=True)
payload = {"dates": dates, "types": types, "plans": plan, "segment_count": len(rows),
           "missing": missing, "ranked": res}
(OUT / "seg_std_result.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
print(json.dumps({"types": types, "plans": plan, "n": len(rows)}, ensure_ascii=False))
for r in res[:6]:
    print(json.dumps(r, ensure_ascii=False))

import os
import csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190125", "20190126", "20190127", "20190128", "20190129", "20190130"]

# trunk inlet segments (single, first recorded segment of each line)
pairs = {
    "西气东输三线": ("霍尔果斯首站", "乌鲁木齐站"),
    "中俄东线": ("黑河首站", "哈尔滨站"),
}
tot = {k: 0.0 for k in pairs}
per_day = []

for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    found = {}
    with p.open(encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            line = (r["管道划分"] or "").strip()
            if line in pairs:
                key = ((r["起点站名"] or "").strip(), (r["终点站名"] or "").strip())
                if key == pairs[line]:
                    found[line] = abs(float(r["管道流量"]))
    assert set(found) == set(pairs), (d, found)
    for k in pairs:
        tot[k] += found[k]
    per_day.append((d, found["西气东输三线"], found["中俄东线"]))

print("trunk inlet (首站出站段) comparison")
print("date, xisan_holg→wlmq, zhongE_heihe→harbin, diff")
for d, a, b in per_day:
    print(f"{d}, {a:.3f}, {b:.3f}, {a-b:+.3f}")
print(f"total: xisan={tot['西气东输三线']:.3f}  zhongE={tot['中俄东线']:.3f}  diff={tot['西气东输三线']-tot['中俄东线']:+.3f}")
print(f"mean daily: xisan={tot['西气东输三线']/6:.3f}  zhongE={tot['中俄东线']/6:.3f}")

import os, csv, statistics, json
from pathlib import Path
from collections import defaultdict

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = [f"2019120{i}" for i in range(1, 7)]
targets = ["中俄东线", "西气东输一线"]

series = {t: [] for t in targets}
segs = {t: {} for t in targets}
for d in dates:
    sums = defaultdict(float); cnts = defaultdict(int)
    with open(DIR / f"{d}_pipeline.csv", encoding="utf-8-sig", newline="") as f:
        for row in csv.DictReader(f):
            name = (row.get("管道划分") or "").strip()
            if name not in targets:
                continue
            try:
                sums[name] += float(row["管道流量"])
            except (KeyError, ValueError):
                continue
            cnts[name] += 1
    for t in targets:
        if cnts[t]:
            series[t].append((d, sums[t] / cnts[t], cnts[t]))
            segs[t][d] = cnts[t]

summary = {}
for t in targets:
    v = [x[1] for x in series[t]]
    m = sum(v) / len(v)
    summary[t] = {
        "days": len(v),
        "daily_means": {d: round(x, 3) for d, x, _ in series[t]},
        "segs_per_day": segs[t],
        "mean_of_daily_means": round(m, 3),
        "min_daily_mean": round(min(v), 3),
        "max_daily_mean": round(max(v), 3),
        "range": round(max(v) - min(v), 3),
        "range_pct_of_mean": round((max(v) - min(v)) / m * 100, 2),
        "stdev": round(statistics.stdev(v), 3),
        "cv_pct": round(statistics.stdev(v) / m * 100, 2),
    }

print(json.dumps(summary, ensure_ascii=False, indent=2))

